// The xAI mark only ships as a raster, and the favicon is a black glyph on
// an opaque white square — as a mask that is just a filled block. The alpha
// below was rebuilt from luminance so the mask cuts the mark itself.
const XAI_MASK = 'data:image/png;base64,'

/* Grok arrives as a mask rather than a simple-icons path, so it has no entry
   in BRANDS and needs its brand colours declared here — otherwise the chip
   hover resolves `--brand-light` to nothing and neither the ring nor the
   glyph changes. Black like the mark itself, lifted on dark the way the
   other black brands are. */
const REDIS_MASK = 'data:image/png;base64,'

const OPENCODE_MASK = 'data:image/png;base64,'

/**
 * Marks that ship as artwork rather than as a simple-icons path, painted with
 * currentColor through a mask so they behave exactly like the drawn ones.
 *
 * Each needed rebuilding: Grok's favicon is a black glyph on an opaque white
 * square, Redis is only published as a raster with a checkerboard baked into
 * the pixels where the transparency should be, and OpenCode's is a white mark
 * on a dark ground. In every case the alpha was derived from the artwork —
 * luminance for the two monochrome ones, chroma for Redis, whose logo is the
 * only saturated thing in its frame.
 */
const MASKS = {
    Grok: { src: XAI_MASK, light: '#000000', dark: '#f5f5f5' },
    Redis: { src: REDIS_MASK, light: '#FF4438', dark: '#FF4438' },
    OpenCode: { src: OPENCODE_MASK, light: '#0F0F11', dark: '#f5f5f5' },
}

const SIZING = 'mark inline-block size-[0.88em] shrink-0 align-[-0.08em]'

/** Some names in the copy are not the brand's own title. */
const ALIASES = {
    'Claude Code': 'Claude',
    Codex: 'OpenAI',
    'React Native': 'React',
}

/**
 * The brand's colours as custom properties, so a wrapper can use them too —
 * the chip's ring picks them up on hover, not just the glyph inside it.
 */
export function brandVars(name) {
    const art = MASKS[name]
    if (art) return { '--brand-light': art.light, '--brand-dark': art.dark }
    const brand = BRANDS[ALIASES[name] ?? name]
    if (!brand) return {}
    return { '--brand-light': brand.light, '--brand-dark': brand.dark }
}

export function hasMark(name) {
    return Boolean(MASKS[name] || BRANDS[ALIASES[name] ?? name])
}

export default function Mark({ name, className }) {
    const art = MASKS[name]
    if (art) {
        return (
            <span
                role="img"
                aria-label={name}
                className={cn(SIZING, className)}
                style={{
                    backgroundColor: 'currentColor',
                    maskImage: `url(${art.src})`,
                    WebkitMaskImage: `url(${art.src})`,
                    maskSize: 'contain',
                    WebkitMaskSize: 'contain',
                    maskRepeat: 'no-repeat',
                    WebkitMaskRepeat: 'no-repeat',
                    maskPosition: 'center',
                    WebkitMaskPosition: 'center',
                }}
            />
        )
    }

    const brand = BRANDS[ALIASES[name] ?? name]
    if (!brand) return null

    return (
        <svg
            viewBox="0 0 24 24"
            role="img"
            aria-label={name}
            fill="currentColor"
            className={cn(SIZING, className)}
            style={{ '--brand-light': brand.light, '--brand-dark': brand.dark }}
        >
            <path d={brand.p} />
        </svg>
    )
}
